  var v = ftAll_();
  for (var i = 0; i < v.length; i++) if (String(v[i][1]) === email && String(v[i][2]) === aid) return String(v[i][0]);
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    v = ftAll_();
    for (var j = 0; j < v.length; j++) if (String(v[j][1]) === email && String(v[j][2]) === aid) return String(v[j][0]);
    var tok = Utilities.getUuid().replace(/-/g, '').slice(0, 12);
