    while (seen[c.id]) c.id += '-x';
    seen[c.id] = 1;
    var e = String(c.e || '').trim().toLowerCase();
    if (e && c.cs !== 'departed' && !map[e]) map[e] = { id: c.id, n: c.n, s: c.s };
