    var q = 'after:' + Math.floor((since - 15 * 60e3) / 1000) + ' -in:chats -in:spam -in:trash';
    var threads = GmailApp.search(q, 0, 100);
    var label = GmailApp.getUserLabelByName(INBOX_LABEL) || GmailApp.createLabel(INBOX_LABEL);
    var sh = inboxSheet_(), last = sh.getLastRow(), done = {};
    if (last > 1) sh.getRange(Math.max(2, last - 3999), 1, Math.min(last - 1, 4000), 1).getValues().forEach(function (r) { done[String(r[0])] = 1; });
    var toks = {}; ftAll_().forEach(function (r) { toks[String(r[0])] = { owner: String(r[1]), aid: String(r[2]) }; });
    var coaches = null, userCoaches = {}, family = {}, writes = {}, rows = [], alerts = {}, ownerLc = OWNER_EMAIL.toLowerCase();
    threads.forEach(function (th) {
