      th.getMessages().forEach(function (m) {
        var rcpt = [m.getTo(), m.getCc(), m.getBcc(), m.getReplyTo()].join(',');
        try { rcpt += ',' + (m.getHeader('Delivered-To') || '') + ',' + (m.getHeader('X-Original-To') || ''); } catch (e) {}
        var re = inboxRe_(); re.lastIndex = 0; var tk = {}, mm;
