          var fam = family[fk], out = !!fam[from];
          var peer = out ? (inboxAddrs_(m.getTo() + ',' + m.getCc()).filter(function (a) { return !fam[a] && a.indexOf('+rd') < 0 && a !== ownerLc; })[0] || '') : from;
          if (!peer) return;
          var co = userCoaches[t.owner][peer] || coaches[peer] || null;
          var dom = peer.split('@')[1] || '';
          var name = co ? co.n : (out ? peer : (fromName || peer)), school = co ? co.s : dom;
          var at = m.getDate(), subj = String(m.getSubject() || '(no subject)').slice(0, 200), body = inboxBody_(m.getPlainBody());
          var data = { cid: co ? co.id : 'em:' + peer, name: name, school: school, em: peer, ch: 'Email', dir: out ? 'out' : 'in',
                       subj: subj, at: at.toISOString(), aid: t.aid, src: 'email', mid: mid };
          if (out) data.body = body; else { data.note = body; data.unread = true; }
          (writes[t.owner] = writes[t.owner] || []).push({ id: 'em_' + mid + (ks.length > 1 ? '_' + tok : ''), data: data });
          rows.push([mid, t.owner, tok, t.aid, out ? 'out' : 'in', at, name, school, out ? peer : from, subj, data.cid]);
          if (!out && at.getTime() > Date.now() - 2 * 864e5) alerts[t.owner] = 1;
        });
      });
      if (hit) { try { th.addLabel(label); if (!direct) th.moveToArchive(); } catch (e) {} }
    });
    Object.keys(writes).forEach(function (em) { try { xWriteLogs_(em, writes[em]); } catch (e) { Logger.log('inbox write ' + em + ': ' + e.message); } });
    if (rows.length) sh.getRange(sh.getLastRow() + 1, 1, rows.length, rows[0].length).setValues(rows);
    Object.keys(alerts).forEach(function (owner) { pushRows_().forEach(function (r) { if (String(r[0]) === owner) pushSend_(String(r[1])); }); });
    P.setProperty('IB_SINCE', String(started));
  } finally { c.remove('ibBusy'); }
}

